765	def validate_survey(obj):
766	    """Validate a decoded survey payload.
767	
768	    Returns (clean_survey, None) on success or (None, error_message) on failure.
769	    Strings are stored trimmed of surrounding whitespace; description keeps its
770	    raw value so Chinese, quotes and newlines are preserved.
771	    """
772	    if not isinstance(obj, dict):
773	        return None, "请求体必须是 JSON 对象"
774	    if "title" not in obj:
775	        return None, "缺少字段 title"
776	    title = obj["title"]
777	    if not isinstance(title, str):
