    def test_stale_save_while_editing_another_survey_is_ignored(self):
        """在另一份问卷的编辑页继续输入时，旧保存结果不能跳转、提示或改写该表单。"""
        survey_a = self.seed_survey(title="问卷甲", description="甲的说明")
