        self.assert_form_state(snapshot, expected, "旧保存成功后的第二次编辑")
        self.assert_no_save_feedback(snapshot, "重新进入的编辑页")
        # 第一次的合法保存仍在服务器完成。
        self.assert_server_survey(survey_id, self.expected_first_save())

